#!/usr/bin/env python3
import sys, os, re, io, csv, gzip, json, datetime as dt
from decimal import Decimal, ROUND_HALF_UP
import xml.etree.ElementTree as ET

KG = {'kg': Decimal(1), 'g': Decimal('0.001'), 'lb': Decimal('0.45359237'),
      'oz': Decimal('0.028349523125')}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
COLS = {
    'east': {'id', 'type', 'shipped', 'gross', 'net', 'status', 'note'},
    'harbor': {'rec', 'ref', 'date', 'weight', 'state'},
    'lakeside': {'id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'},
    'river': {'t', 'ref', 'shipped', 'weight', 'status'},
    'west': {'id', 'typ', 'shipped', 'weight', 'status', 'note'},
}
DELIM = {'east': ',', 'harbor': '|', 'lakeside': ',', 'river': '\t', 'west': ';'}
MONTHS = {m: i + 1 for i, m in enumerate(
    ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'])}
HARBOR_ST = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled',
             'RET': 'returned', 'HLD': 'held'}
FW_ST = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}


def decode(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be')
    head = b[:1000].split(b'\n')[:10]
    for ln in head:
        m = re.match(rb'#\s*charset\s*:\s*([\w.\-]+)', ln.strip())
        if m:
            return b.decode(m.group(1).decode())
    return b.decode('utf-8')


def norm_id(s):
    m = re.match(r'^\s*SH\W*0*(\d+)\s*$', s or '', re.I)
    return int(m.group(1)) if m else None


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


def rtype(s):
    s = (s or '').strip().lower()
    if s.startswith('v'):
        return 'void'
    if s.startswith('c') or s.startswith('a'):
        return 'corr'
    return 'new'


def parse_date(s, form):
    s = (s or '').strip()
    form = (form or '').strip().upper()
    if 'T' in s.upper() and ':' in s:
        d = dt.datetime.fromisoformat(s.replace('z', 'Z'))
        if d.tzinfo is not None:
            d = d.astimezone(dt.timezone.utc)
        return d.date()
    if form == 'SERIAL' or (re.fullmatch(r'\d+(\.\d+)?', s) and len(s) <= 6):
        return dt.date(1899, 12, 30) + dt.timedelta(days=int(float(s)))
    if re.fullmatch(r'\d{8}', s):
        return dt.date(int(s[:4]), int(s[4:6]), int(s[6:]))
    if re.fullmatch(r'\d{7}', s):
        return dt.date(int(s[:4]), 1, 1) + dt.timedelta(days=int(s[4:]) - 1)
    parts = [p for p in re.split(r'[^0-9A-Za-z]+', s) if p]
    if len(parts) != 3:
        raise ValueError('bad date ' + s)
    if parts[1][:3].lower() in MONTHS:
        return dt.date(int(parts[2]), MONTHS[parts[1][:3].lower()], int(parts[0]))
    if len(parts[0]) == 4:
        return dt.date(int(parts[0]), int(parts[1]), int(parts[2]))
    if form.startswith('MM'):
        return dt.date(int(parts[2]), int(parts[0]), int(parts[1]))
    return dt.date(int(parts[2]), int(parts[1]), int(parts[0]))


def parse_num(s, style):
    s = s.strip()
    if style == 'comma':
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    return Decimal(s)


def weight_kg(s, style, unit):
    s = (s or '').strip()
    m = re.match(r'^(.*?)\s*(kg|g|lb|oz)$', s, re.I)
    if m:
        s, unit = m.group(1), m.group(2).lower()
    return parse_num(s, style) * KG[(unit or 'kg').lower()]


def rec(kind, num, date=None, w=None, st=None):
    return {'kind': kind, 'num': num, 'date': date, 'kg': w, 'status': st}


def read_delimited(depot, text):
    delim = DELIM[depot]
    cols = COLS[depot]
    recs = []
    lines = text.split('\n')
    rows = []  # ('dir', name, val) | ('row', fields)
    cur = None
    for l in lines:
        if l.endswith('\r'):
            l = l[:-1]
        if cur is None:
            if l.strip() == '':
                continue
            if l.startswith('#'):
                rows.append(('c', l))
                continue
            cur = l
        else:
            cur += '\n' + l
        if delim == ',' and cur.count('"') % 2 == 1:
            continue
        if delim == ',':
            row = next(csv.reader(io.StringIO(cur), delimiter=','), [])
        else:
            row = cur.split(delim)
        rows.append(('r', row))
        cur = None
    if cur is not None:
        rows.append(('r', next(csv.reader(io.StringIO(cur), delimiter=delim), [])))
    seq = None
    header = None
    dform = {'east': 'YMD', 'lakeside': 'iso', 'river': 'MM/DD/YYYY', 'harbor': 'iso',
             'west': 'DD.MM.YYYY'}[depot]
    unit = {'east': 'kg', 'river': 'kg', 'west': 'kg', 'lakeside': 'kg', 'harbor': 'kg'}[depot]
    style = 'comma' if depot == 'west' else 'dot'
    for k, v in rows:
        if k == 'c':
            m = re.match(r'#\s*harbor export\s+seq=(\d+)', v)
            if m:
                seq = int(m.group(1))
                continue
            m = re.match(r'#\s*([^:]+?)\s*:\s*(.*?)\s*$', v)
            if not m:
                continue
            name, val = m.group(1).lower(), m.group(2)
            name = re.sub(r'\s+', ' ', name)
            if name == 'seq':
                seq = int(val)
            elif name in ('dates', 'date format'):
                dform = val
            elif name in ('unit', 'weight unit'):
                mm = re.match(r'(kg|g|lb|oz)\b', val.strip(), re.I)
                if mm:
                    unit = mm.group(1).lower()
                if 'decimal comma' in val.lower():
                    style = 'comma'
            continue
        row = [x.strip() if depot != 'east' or True else x for x in v]
        low = [x.strip().lower() for x in row]
        if low and all(x in cols for x in low) and len(set(low)) == len(low) and len(low) > 1:
            header = low
            continue
        if header is None:
            continue
        rowunit = None
        if len(row) == len(header) + 1:
            # row carries its own unit right after the weight column
            wi = None
            for i, h in enumerate(header):
                if h in ('gross', 'weight') or re.search(r'_(kg|g|lb|oz)$', h):
                    wi = i
                    break
            if wi is not None and wi + 1 < len(row) and row[wi + 1].lower() in KG:
                rowunit = row[wi + 1].lower()
                del row[wi + 1]
        if len(row) != len(header):
            continue
        d = dict(zip(header, row))
        idf = d.get('id', d.get('ref'))
        num = norm_id(idf)
        if num is None:
            continue
        kind = rtype(d.get('type', d.get('rec', d.get('kind', d.get('typ', d.get('t'))))))
        if kind == 'void':
            recs.append(rec(kind, num))
            continue
        wcol = None
        u = rowunit or unit
        for h in header:
            if h in ('gross', 'weight', 'gross_kg'):
                wcol = h
                m = re.search(r'_(kg|g|lb|oz)$', h)
                if m:
                    u = m.group(1)
        wk = weight_kg(d[wcol], style, u)
        ds = d.get('shipped', d.get('date'))
        st = d.get('status', d.get('state'))
        if depot == 'harbor':
            st = HARBOR_ST.get(st.strip().upper(), st)
        recs.append(rec(kind, num, parse_date(ds, dform), wk, norm_status(st)))
    return seq, recs


def read_south(text):
    seq = None
    layout = None
    recs = []
    specs = {  # name: length, type, id, shipped, weight, status, wunit
        'FW1': (42, (9, 10), (0, 9), (10, 17), (17, 25), 25, 'g', 1),
        'FW2': (43, (0, 1), (1, 10), (10, 18), (18, 26), 26, 'cg', 1),
        'FW3': (41, (16, 17), (0, 9), (9, 16), (17, 24), 24, 'dlb', 1),
    }
    bylen = {v[0]: k for k, v in specs.items()}
    for l in text.split('\n'):
        l = l.rstrip('\r')
        if l.startswith('#LAYOUT'):
            layout = l.split()[1]
            continue
        if l.startswith('#SEQ'):
            seq = int(l.split()[1])
            continue
        if l.startswith('#') or '\f' in l or l.strip() == '':
            continue
        name = bylen.get(len(l), layout)
        if name not in specs or (len(l) != specs[name][0] and len(l) < specs[name][0] - 16):
            continue
        sp = specs[name]
        num = norm_id(l[sp[2][0]:sp[2][1]])
        if num is None:
            continue
        kind = rtype(l[sp[1][0]:sp[1][1]])
        if kind == 'void':
            recs.append(rec(kind, num))
            continue
        ds = l[sp[3][0]:sp[3][1]]
        raw = int(l[sp[4][0]:sp[4][1]])
        if sp[6] == 'g':
            w = Decimal(raw) * KG['g']
        elif sp[6] == 'cg':
            w = Decimal(raw) / 100
        else:
            w = Decimal(raw) / 10 * KG['lb']
        recs.append(rec(kind, num, parse_date(ds, ''), w, norm_status(FW_ST.get(l[sp[5]], l[sp[5]]))))
    return seq, recs


def read_north(text):
    seq = None
    recs = []
    for l in text.split('\n'):
        l = l.strip()
        if not l:
            continue
        v = json.loads(l)
        for o in (v if isinstance(v, list) else [v]):
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if seq is None and 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            num = norm_id(str(o.get('id', '')))
            if num is None:
                continue
            kind = rtype(o.get('kind'))
            if kind == 'void':
                recs.append(rec(kind, num))
                continue
            w = None
            for k, val in o.items():
                m = re.fullmatch(r'weight(?:_(kg|g|lb|oz))?', k)
                if m:
                    w = weight_kg(str(val), 'dot', m.group(1) or 'kg')
            recs.append(rec(kind, num, parse_date(o['shipped_at'], ''), w, norm_status(o.get('status'))))
    return seq, recs


def read_central(text):
    text = re.sub(r'^\s*<\?xml[^>]*\?>', '', text.lstrip('\ufeff'))
    root = ET.fromstring(text)
    seq = int(root.get('seq')) if root.get('seq') else None
    runit = root.get('weight-unit', 'kg')
    recs = []
    for e in root.iter('shipment'):
        num = norm_id(e.get('id'))
        if num is None:
            continue
        kind = rtype(e.get('type'))
        if kind == 'void':
            recs.append(rec(kind, num))
            continue
        we = e.find('weight')
        w = weight_kg(we.text, 'dot', we.get('unit') or runit)
        sh = e.get('shipped')
        if sh is None:
            sh = e.findtext('shipped')
        recs.append(rec(kind, num, parse_date(sh, ''), w, norm_status(e.findtext('status'))))
    return seq, recs


def main():
    ddir, out = sys.argv[1], sys.argv[2]
    byd = {}
    for f in sorted(os.listdir(ddir)):
        p = os.path.join(ddir, f)
        if not os.path.isfile(p):
            continue
        depot = f.split('-')[0]
        text = decode(p)
        if depot == 'central':
            r = read_central(text)
        elif depot == 'south':
            r = read_south(text)
        elif depot == 'north':
            r = read_north(text)
        elif depot in DELIM:
            r = read_delimited(depot, text)
        else:
            byd.setdefault(depot, [])
            continue
        byd.setdefault(depot, []).append((r[0] if r[0] is not None else 0, f, r[1]))
    corrections = resends = 0
    current = {}
    for depot, files in byd.items():
        cur = {}
        for seq, f, recs in sorted(files, key=lambda x: (x[0], x[1])):
            for r in recs:
                n = r['num']
                if r['kind'] == 'new':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r['kind'] == 'corr':
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur
    rank = lambda d: ORDER.index(d) if d in ORDER else len(ORDER)
    owners = {}
    for depot in sorted(current, key=lambda d: (rank(d), d)):
        for n, r in current[depot].items():
            owners.setdefault(n, []).append((depot, r))
    handovers = sum(1 for v in owners.values() if len(v) > 1)
    dep = {d: [0, Decimal(0)] for d in byd}
    mon = {}
    for n, v in owners.items():
        depot, r = v[0]
        if r['status'] not in ('delivered', 'delivered_late'):
            continue
        dep[depot][0] += 1
        dep[depot][1] += r['kg']
        m = mon.setdefault('%04d-%02d' % (r['date'].year, r['date'].month), [0, Decimal(0)])
        m[0] += 1
        m[1] += r['kg']
    q = lambda x: float(x.quantize(Decimal('0.01'), ROUND_HALF_UP))
    res = {'depots': {d: {'shipments': dep[d][0], 'total_kg': q(dep[d][1])} for d in sorted(dep)},
           'months': {m: {'shipments': mon[m][0], 'total_kg': q(mon[m][1])} for m in sorted(mon)},
           'corrections_applied': corrections, 'resends_dropped': resends, 'handovers': handovers}
    with open(out, 'w') as fh:
        json.dump(res, fh, indent=2)


main()
